  function renderStock() { const list = db.parts.filter(p => `${p.name} ${p.sku} ${p.category}`.toLowerCase().includes(pageSearch.toLowerCase()) && (pageFilter === 'Todos' || (pageFilter === 'Estoque baixo' && p.stock > 0 && p.stock <= p.min) || (pageFilter === 'Esgotado' && p.stock <= 0) || (pageFilter === 'Disponível' && p.stock > p.min))); const per = 10, pagesCount = Math.max(1, Math.ceil(list.length / per)); currentPage = Math.min(currentPage, pagesCount); const shown = list.slice((currentPage - 1) * per, currentPage * per); content.innerHTML = pageHead('CATÁLOGO DE PEÇAS', 'Estoque', `${db.parts.length} itens cadastrados · ${lowParts().length} para repor`, '＋ Cadastrar peça', 'new-part') + `<div class="filter-row"><div class="search-box"><input class="field" id="searchInput" placeholder="Buscar peça, código ou categoria..." value="${esc(pageSearch)}"></div><select class="select" id="filterSelect"><option>Todos</option><option ${pageFilter === 'Disponível' ? 'selected' : ''}>Disponível</option><option ${pageFilter === 'Estoque baixo' ? 'selected' : ''}>Estoque baixo</option><option ${pageFilter === 'Esgotado' ? 'selected' : ''}>Esgotado</option></select><button class="btn btn-light" data-action="export">↓ Exportar CSV</button></div>` + tableCard('Peças cadastradas', `${list.length} resultados`, ['Peça / código', 'Categoria', 'Em estoque', 'Mínimo', 'Custo unitário', 'Situação', 'Ações'], partRows(shown), 'Nenhuma peça encontrada.') + pagination(list.length, per, pagesCount);
  }
  function renderMovements() { let list = [...db.movements].filter(m => { const p = getPart(m.partId), q = `${p?.name || ''} ${m.reason} ${m.ref || ''}`.toLowerCase(); return q.includes(pageSearch.toLowerCase()) && (pageFilter === 'Todos' || m.type === pageFilter); }).sort((a, b) => b.date.localeCompare(a.date) || b.id.localeCompare(a.id)); const per = 12, n = Math.max(1, Math.ceil(list.length / per)); currentPage = Math.min(currentPage, n); content.innerHTML = pageHead('HISTÓRICO DO ESTOQUE', 'Movimentações', `${db.movements.length.toLocaleString('pt-BR')} registros · entradas e saídas da oficina`, '＋ Registrar movimentação', 'choose-movement') + `<div class="filter-row"><div class="search-box"><input class="field" id="searchInput" placeholder="Buscar peça, motivo ou referência..." value="${esc(pageSearch)}"></div><select class="select" id="filterSelect"><option>Todos</option><option ${pageFilter === 'Entrada' ? 'selected' : ''}>Entrada</option><option ${pageFilter === 'Saída' ? 'selected' : ''}>Saída</option></select><button class="btn btn-light" data-action="export-movements">↓ Exportar CSV</button></div>` + tableCard('Registro de movimentações', `${list.length.toLocaleString('pt-BR')} registros`, ['Data', 'Peça', 'Tipo', 'Quantidade', 'Motivo', 'Referência'], movementRows(list.slice((currentPage - 1) * per, currentPage * per)), 'Nenhuma movimentação encontrada.') + pagination(list.length, per, n); }
  function pagination(total, per, count) { return `<div class="pagination"><span>Exibindo ${total ? (currentPage - 1) * per + 1 : 0}–${Math.min(currentPage * per, total)} de ${total.toLocaleString('pt-BR')}</span><div class="pagination-buttons"><button data-action="page" data-page="${Math.max(1, currentPage - 1)}" ${currentPage === 1 ? 'disabled' : ''}>‹</button>${Array.from({ length: Math.min(count, 5) }, (_, i) => { const pg = Math.max(1, Math.min(count - 4, currentPage - 2)) + i; return `<button class="${pg === currentPage ? 'current' : ''}" data-action="page" data-page="${pg}">${pg}</button>`; }).join('')}<button data-action="page" data-page="${Math.min(count, currentPage + 1)}" ${currentPage === count ? 'disabled' : ''}>›</button></div></div>`; }
