    const featureFields = `<div class="form-field full"><label>Permissões por módulo</label><p class="form-hint">Marque apenas as áreas liberadas para esta oficina.</p><div class="permission-grid">${permissionCatalog.map(([key, label]) => `<label class="permission-option"><input type="checkbox" name="perm_${key}" ${permissions[key] ? 'checked' : ''}><span><strong>${label}</strong><small>${permissions[key] ? 'Acesso liberado' : 'Acesso bloqueado'}</small></span></label>`).join('')}</div></div>`;
    modalForm(editing ? 'Editar cliente e acesso' : 'Cadastrar oficina cliente', fields + featureFields, editing ? 'Salvar cadastro' : 'Cadastrar cliente', (v) => saveAdminClient(v, client?.id) ? true : false, 'ADMINISTRAÇÃO DE CLIENTES');
